css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .banco{border: 1.5px dashed #000; border-radius: 8px; padding: 5px 10px; text-align: center; font-size: 13px; font-weight: 700; margin-bottom: 6px;}
.mz .nombrar-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .nombrar-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 8px; display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .nombrar-caja svg{width: 86px; height: 56px;}
.mz .nombrar-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .letras-fila{display: grid; grid-template-columns: repeat(6, 1fr); gap: 6px; margin-bottom: 7px;}
.mz .letra-item{border: 1.5px dashed #000; border-radius: 8px; padding: 3px 4px 4px; display: flex; flex-direction: column; align-items: center; gap: 1px;}
.mz .letra-item svg{width: 58px; height: 44px;}
.mz .letra-tag{font-family: sans-serif; font-weight: 800; font-size: 12px;}
.mz .clasif-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 12px;}
.mz .clasif-caja{border: 1.5px solid var(--bosque); border-radius: 8px; overflow: hidden;}
.mz .clasif-titulo{background: #e3e3e3; border-bottom: 1.5px solid var(--bosque); text-align: center; font-family: sans-serif; font-weight: 800; font-size: 12.5px; padding: 3px 0; letter-spacing: 1px;}
.mz .clasif-lineas{display: flex; justify-content: space-around; gap: 10px; padding: 12px 16px 14px;}
.mz .clasif-lineas span{border-bottom: 1.5px solid var(--bosque); width: 44px; height: 24px; display: inline-block;}
.mz .contar-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;}
.mz .contar-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 8px; display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .contar-caja svg{width: 138px; height: 66px;}
.mz .contar-resp{font-size: 12.5px; font-weight: 700; display: flex; align-items: center; gap: 6px;}
.mz .contar-hueco{border: 1.5px solid var(--bosque); border-radius: 6px; width: 36px; height: 26px; display: inline-block;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 3px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
.mz .camino-zona{border: 1.5px solid var(--bosque); border-radius: 8px; width: 100%; height: 140px; position: relative;}
.mz .camino-punto{position: absolute; top: 50%; width: 12px; height: 12px; background: #000; border-radius: 50%; transform: translateY(-50%);}
.mz .camino-salida{left: 22px;}
.mz .camino-meta{right: 22px;}
.mz .camino-label{position: absolute; font-family: sans-serif; font-weight: 800; font-size: 10.5px; top: calc(50% + 10px);}
.mz .camino-label.salida{left: 6px;}
.mz .camino-label.meta{right: 10px;}
